-- Stores the frozen A5Q_C2 GPT Native packet in unit_metadata and hands it to GPT Native as an operational event
-- (HANDOFF_DEEP_CONTEXT). Data only: no action spec, checkpoint status or assertion changes. C2 stays PENDING.
-- The event carries a pointer to the packet, its hashes and the instructions text; it declares no acceptance.
-- Tier: OWNER_APPROVED_GPT_NATIVE_IN_CHAT_EQUIVALENT (not provider-attested).
BEGIN;
DO $a5q_c2_prep$
DECLARE
 v_plan constant text := 'PROGRAMMING_AGENT_ANALYSIS_REMEDIATION_V1';
 v_unit constant text := 'A5Q';
 v_cp constant text := 'A5Q_C2';
 v_wi constant bigint := 1115;
 v_exec constant text := 'ANALYSIS_QUAL_C2_GPT_HANDOFF_V1|A5Q_C2';
 v_packet_sha constant text := '2408c9a1b4bbb8eb90030dcac0d27468c098dc029483133126204366740be056';
 v_packet jsonb := $pkt${"checkpoint":"C2","deterministic_checks":{"forbidden_solution_patterns":["\\bredis\\b","\\bkafka\\b","\\bpostgres\\w*","\\breact\\b","\\bsql\\b","\\bapi\\b","\\bendpoint\\b","\\btrigger\\b","\\bmigraci\\w+","\\bmicroservic\\w+","\\brpc\\b","\\bedge function\\b","\\btabla\\b","\\bbase de datos\\b","\\bcomponente\\b"],"min_distinct_gaps":5,"pending_keys":["blocking","decision_id","gap_ref","impact_ref","owner_role","question","status"],"request_ref_equals":"REQ-LF-A1Q-C2-PILOT-0001"},"evidence_tier":"OWNER_APPROVED_GPT_NATIVE_IN_CHAT_EQUIVALENT","input":{"input_literal":"{\n  \"a4_stage_output\": {\n    \"consumers\": [],\n    \"dependency_paths\": [],\n    \"direct_impacts\": [],\n    \"evidence_refs\": [\n      \"supabase://programacion.engineering_plan_units/A1Q#unit_metadata.gpt_native_packets_v1.A1Q_C2\",\n      \"supabase://public.lf_eventos/20843\",\n      \"gap:TARGET_IDENTITY_UNRESOLVED\",\n      \"gap:TARGET_AUTHORITY_NOT_SUPPLIED\",\n      \"gap:IMPLEMENTATION_STATE_UNVERIFIED\",\n      \"gap:AS_IS_BASELINE_MISSING\",\n      \"gap:SAVINGS_SEMANTICS_UNRESOLVED\",\n      \"gap:OFFER_ACCEPTANCE_BOUNDARY_UNRESOLVED\",\n      \"gap:INSTALLMENT_DISTINCTION_UNRESOLVED\",\n      \"gap:ACCEPTANCE_EVIDENCE_MISSING\"\n    ],\n    \"impact_statement\": \"La evidencia disponible consiste en un paquete congelado de solicitud y su evento de traspaso, con coincidencia de hashes verificada por A3. Esas fuentes respaldan la trazabilidad del contexto, pero no acreditan el mapa de impacto de la funcionalidad solicitada. A3 declaró UNKNOWN para autoridad e implementación, NONE_SUPPLIED para línea base y NEED_MORE_EVIDENCE para suficiencia. Por ello no se pueden afirmar efectos directos o indirectos concretos, identificar consumidores funcionales reales, reconstruir rutas de dependencia ni concluir que alguna categoría carezca de impactos. La solicitud identifica una necesidad de los clientes, pero esa intención no demuestra efectos observados ni vínculos implementados. Las diez incógnitas registradas delimitan lo que falta investigar sin inventar una solución técnica.\",\n    \"indirect_impacts\": [],\n    \"no_absence_claimed\": true,\n    \"request_ref\": \"REQ-LF-A1Q-C2-PILOT-0001\",\n    \"schema_version\": \"A4_IMPACT_MAP_OUTPUT_V1\",\n    \"unresolved_material_impacts\": [\n      {\n        \"category\": \"DIRECT\",\n        \"gap_ref\": \"TARGET_IDENTITY_UNRESOLVED\",\n        \"impact_id\": \"A4-DIRECT-001\",\n        \"statement\": \"Se desconoce qué capacidad funcional, pantalla, canal o segmento exacto recibiría el cambio. No es posible identificar los objetos directamente afectados.\"\n      },\n      {\n        \"category\": \"DIRECT\",\n        \"gap_ref\": \"SAVINGS_SEMANTICS_UNRESOLVED\",\n        \"impact_id\": \"A4-DIRECT-002\",\n        \"statement\": \"No está definida la semántica autorizada del ahorro ni su base de comparación. Se desconoce qué información económica concreta debería verse afectada.\"\n      },\n      {\n        \"category\": \"DIRECT\",\n        \"gap_ref\": \"AS_IS_BASELINE_MISSING\",\n        \"impact_id\": \"A4-DIRECT-003\",\n        \"statement\": \"No se conoce el comportamiento actual ni su diferencia respecto de la necesidad solicitada. No puede establecerse qué comportamiento cambiaría realmente.\"\n      },\n      {\n        \"category\": \"INDIRECT\",\n        \"gap_ref\": \"INSTALLMENT_DISTINCTION_UNRESOLVED\",\n        \"impact_id\": \"A4-INDIRECT-001\",\n        \"statement\": \"Se desconoce si la interpretación del ahorro y su distinción respecto de las cuotas afecta otros comportamientos funcionales o información económica. No existe evidencia para afirmar ni descartar esos efectos.\"\n      },\n      {\n        \"category\": \"INDIRECT\",\n        \"gap_ref\": \"ACCEPTANCE_EVIDENCE_MISSING\",\n        \"impact_id\": \"A4-INDIRECT-002\",\n        \"statement\": \"No se dispone de evidencia suficiente para determinar si el cambio produciría efectos indirectos sobre comprensión, abandono o aceptación de ofertas, ni cómo se verificarían.\"\n      },\n      {\n        \"category\": \"CONSUMER\",\n        \"gap_ref\": \"TARGET_IDENTITY_UNRESOLVED\",\n        \"impact_id\": \"A4-CONSUMER-001\",\n        \"statement\": \"La solicitud menciona clientes del marketplace como destinatarios previstos, pero no identifica segmentos, canales ni consumidores funcionales concretos que deban recibir o utilizar la información.\"\n      },\n      {\n        \"category\": \"CONSUMER\",\n        \"gap_ref\": \"OFFER_ACCEPTANCE_BOUNDARY_UNRESOLVED\",\n        \"impact_id\": \"A4-CONSUMER-002\",\n        \"statement\": \"No se identifican consumidores posteriores de información relacionada con la oferta o su aceptación. La ausencia de esa identificación no demuestra que dichos consumidores no existan.\"\n      },\n      {\n        \"category\": \"DEPENDENCY\",\n        \"gap_ref\": \"TARGET_AUTHORITY_NOT_SUPPLIED\",\n        \"impact_id\": \"A4-DEPENDENCY-001\",\n        \"statement\": \"No se conocen las reglas, contratos o decisiones de autoridad que gobiernan el ahorro y su comunicación. Por tanto, no pueden identificarse dependencias normativas o funcionales verificadas.\"\n      },\n      {\n        \"category\": \"DEPENDENCY\",\n        \"gap_ref\": \"IMPLEMENTATION_STATE_UNVERIFIED\",\n        \"impact_id\": \"A4-DEPENDENCY-002\",\n        \"statement\": \"No se conoce si existe una implementación de la capacidad solicitada. No es posible reconstruir dependencias entre elementos implementados ni demostrar su inexistencia.\"\n      },\n      {\n        \"category\": \"DEPENDENCY\",\n        \"gap_ref\": \"OFFER_ACCEPTANCE_BOUNDARY_UNRESOLVED\",\n        \"impact_id\": \"A4-DEPENDENCY-003\",\n        \"statement\": \"No está acreditado el límite funcional entre una oferta disponible y su aceptación. Se desconoce si existen dependencias materiales asociadas a esas transiciones.\"\n      }\n    ]\n  }\n}","input_origin":"A4Q_C2 GPT Native RAW (raw_output_sha256 58396efc6d1a31c443e151b54d1267a6ea64b6c5c34029d200048647435b40b5)","input_sha256":"2083abe58c6bfac48f50b0e32edc671e4dc0ee94cb0d3e1fa3b18a1963dbbeb7","request_ref":"REQ-LF-A1Q-C2-PILOT-0001"},"limits":{"checkpoint_transition":false,"db_write":false,"independent_assurance_admitted":false,"provider_attested":false,"real_execution_receipt":false,"transcript_is_provider_evidence":false},"output_contract":{"required_keys":["schema_version","request_ref","current_decisions","current_decisions_basis","pending_decisions","decisions_approved_by_agent","evidence_refs","decision_statement","no_self_approval"],"schema":"A5_DECISIONS_OUTPUT_V1","validator":"analysis_qualification_a5q_c2_gpt_native_packet_v1.py::semantic_checks"},"owner_approval_doc":"docs/programming-agent/ANALYSIS_C2C3_GPT_NATIVE_APPROVED_EQUIVALENT_V1.md","packet_sha256":"2408c9a1b4bbb8eb90030dcac0d27468c098dc029483133126204366740be056","producer_mode":"GPT_NATIVE","profile_source":{"ref":"profiles/programming_analysis_lf/SKILL.md","sha256":"91a7b47c3d84f1d5aea48f3fd475134d9c56c718461d1b649c4a89d53980508f"},"prompt_for_gpt":"Este mensaje es independiente: ignora cualquier otro paquete o salida anterior de este chat. Eres el productor de la etapa A5 (decisiones) del perfil de análisis. Recibes la salida de la etapa A4 (abajo). Conserva las decisiones materiales que debe tomar el propietario humano. NO apruebes, elijas ni decidas nada: no resuelvas ADRs ni decisiones de producto. Distingue decisiones vigentes (solo si la entrada trae una fuente que las respalde; si no, la lista va vacía) de decisiones nuevas pendientes. Las únicas referencias válidas son las evidence_refs de la entrada y 'impact:<impact_id>' para cada impacto no resuelto. No infieras solución técnica. Devuelve SOLO un objeto JSON, sin texto adicional, con exactamente estas claves: schema_version, request_ref, current_decisions, current_decisions_basis, pending_decisions, decisions_approved_by_agent, evidence_refs, decision_statement, no_self_approval. schema_version='A5_DECISIONS_OUTPUT_V1'. request_ref='REQ-LF-A1Q-C2-PILOT-0001'. current_decisions: lista (vacía si no hay fuente vigente). current_decisions_basis: texto que explica por qué está vacía o de dónde salen. pending_decisions: lista de {decision_id (único), question (una pregunta, texto que termina en '?'), owner_role='OWNER_HUMAN', blocking (booleano), gap_ref (un gap_code de la entrada), impact_ref (un impact_id de la entrada cuyo gap_ref coincida con el gap_ref), status='PENDING_OWNER_DECISION'}; deben cubrir al menos 5 brechas distintas y al menos una debe ser blocking. decisions_approved_by_agent: lista vacía. evidence_refs: lista no vacía de referencias válidas. decision_statement: texto que explica qué decide el propietario y qué no decidió el agente. no_self_approval=true.\n\nENTRADA (JSON):\n{\n  \"a4_stage_output\": {\n    \"consumers\": [],\n    \"dependency_paths\": [],\n    \"direct_impacts\": [],\n    \"evidence_refs\": [\n      \"supabase://programacion.engineering_plan_units/A1Q#unit_metadata.gpt_native_packets_v1.A1Q_C2\",\n      \"supabase://public.lf_eventos/20843\",\n      \"gap:TARGET_IDENTITY_UNRESOLVED\",\n      \"gap:TARGET_AUTHORITY_NOT_SUPPLIED\",\n      \"gap:IMPLEMENTATION_STATE_UNVERIFIED\",\n      \"gap:AS_IS_BASELINE_MISSING\",\n      \"gap:SAVINGS_SEMANTICS_UNRESOLVED\",\n      \"gap:OFFER_ACCEPTANCE_BOUNDARY_UNRESOLVED\",\n      \"gap:INSTALLMENT_DISTINCTION_UNRESOLVED\",\n      \"gap:ACCEPTANCE_EVIDENCE_MISSING\"\n    ],\n    \"impact_statement\": \"La evidencia disponible consiste en un paquete congelado de solicitud y su evento de traspaso, con coincidencia de hashes verificada por A3. Esas fuentes respaldan la trazabilidad del contexto, pero no acreditan el mapa de impacto de la funcionalidad solicitada. A3 declaró UNKNOWN para autoridad e implementación, NONE_SUPPLIED para línea base y NEED_MORE_EVIDENCE para suficiencia. Por ello no se pueden afirmar efectos directos o indirectos concretos, identificar consumidores funcionales reales, reconstruir rutas de dependencia ni concluir que alguna categoría carezca de impactos. La solicitud identifica una necesidad de los clientes, pero esa intención no demuestra efectos observados ni vínculos implementados. Las diez incógnitas registradas delimitan lo que falta investigar sin inventar una solución técnica.\",\n    \"indirect_impacts\": [],\n    \"no_absence_claimed\": true,\n    \"request_ref\": \"REQ-LF-A1Q-C2-PILOT-0001\",\n    \"schema_version\": \"A4_IMPACT_MAP_OUTPUT_V1\",\n    \"unresolved_material_impacts\": [\n      {\n        \"category\": \"DIRECT\",\n        \"gap_ref\": \"TARGET_IDENTITY_UNRESOLVED\",\n        \"impact_id\": \"A4-DIRECT-001\",\n        \"statement\": \"Se desconoce qué capacidad funcional, pantalla, canal o segmento exacto recibiría el cambio. No es posible identificar los objetos directamente afectados.\"\n      },\n      {\n        \"category\": \"DIRECT\",\n        \"gap_ref\": \"SAVINGS_SEMANTICS_UNRESOLVED\",\n        \"impact_id\": \"A4-DIRECT-002\",\n        \"statement\": \"No está definida la semántica autorizada del ahorro ni su base de comparación. Se desconoce qué información económica concreta debería verse afectada.\"\n      },\n      {\n        \"category\": \"DIRECT\",\n        \"gap_ref\": \"AS_IS_BASELINE_MISSING\",\n        \"impact_id\": \"A4-DIRECT-003\",\n        \"statement\": \"No se conoce el comportamiento actual ni su diferencia respecto de la necesidad solicitada. No puede establecerse qué comportamiento cambiaría realmente.\"\n      },\n      {\n        \"category\": \"INDIRECT\",\n        \"gap_ref\": \"INSTALLMENT_DISTINCTION_UNRESOLVED\",\n        \"impact_id\": \"A4-INDIRECT-001\",\n        \"statement\": \"Se desconoce si la interpretación del ahorro y su distinción respecto de las cuotas afecta otros comportamientos funcionales o información económica. No existe evidencia para afirmar ni descartar esos efectos.\"\n      },\n      {\n        \"category\": \"INDIRECT\",\n        \"gap_ref\": \"ACCEPTANCE_EVIDENCE_MISSING\",\n        \"impact_id\": \"A4-INDIRECT-002\",\n        \"statement\": \"No se dispone de evidencia suficiente para determinar si el cambio produciría efectos indirectos sobre comprensión, abandono o aceptación de ofertas, ni cómo se verificarían.\"\n      },\n      {\n        \"category\": \"CONSUMER\",\n        \"gap_ref\": \"TARGET_IDENTITY_UNRESOLVED\",\n        \"impact_id\": \"A4-CONSUMER-001\",\n        \"statement\": \"La solicitud menciona clientes del marketplace como destinatarios previstos, pero no identifica segmentos, canales ni consumidores funcionales concretos que deban recibir o utilizar la información.\"\n      },\n      {\n        \"category\": \"CONSUMER\",\n        \"gap_ref\": \"OFFER_ACCEPTANCE_BOUNDARY_UNRESOLVED\",\n        \"impact_id\": \"A4-CONSUMER-002\",\n        \"statement\": \"No se identifican consumidores posteriores de información relacionada con la oferta o su aceptación. La ausencia de esa identificación no demuestra que dichos consumidores no existan.\"\n      },\n      {\n        \"category\": \"DEPENDENCY\",\n        \"gap_ref\": \"TARGET_AUTHORITY_NOT_SUPPLIED\",\n        \"impact_id\": \"A4-DEPENDENCY-001\",\n        \"statement\": \"No se conocen las reglas, contratos o decisiones de autoridad que gobiernan el ahorro y su comunicación. Por tanto, no pueden identificarse dependencias normativas o funcionales verificadas.\"\n      },\n      {\n        \"category\": \"DEPENDENCY\",\n        \"gap_ref\": \"IMPLEMENTATION_STATE_UNVERIFIED\",\n        \"impact_id\": \"A4-DEPENDENCY-002\",\n        \"statement\": \"No se conoce si existe una implementación de la capacidad solicitada. No es posible reconstruir dependencias entre elementos implementados ni demostrar su inexistencia.\"\n      },\n      {\n        \"category\": \"DEPENDENCY\",\n        \"gap_ref\": \"OFFER_ACCEPTANCE_BOUNDARY_UNRESOLVED\",\n        \"impact_id\": \"A4-DEPENDENCY-003\",\n        \"statement\": \"No está acreditado el límite funcional entre una oferta disponible y su aceptación. Se desconoce si existen dependencias materiales asociadas a esas transiciones.\"\n      }\n    ]\n  }\n}","request_sha256":"c3a1c2e7353c4b4dd8ce083d75e30a7b97e9ec07f47b0375cc3ebd5039c99781","run_id":"A5Q_C2-GPTN-PILOT-0001","schema":"ANALYSIS_GPT_NATIVE_PACKET_V1","stage_output_selector":"A5","subject_ref":"PROGRAMMING_AGENT_ANALYSIS_REMEDIATION_V1/A5Q/A5Q_C2","unit":"A5"}$pkt$;
 v_m jsonb; v_before_specs jsonb; v_before_cps text; v_after_cps text; v_stored jsonb; v_id bigint; v_p jsonb;
BEGIN
 IF v_packet->>'packet_sha256' IS DISTINCT FROM v_packet_sha OR v_packet->>'subject_ref' <> v_plan||'/'||v_unit||'/'||v_cp
  THEN RAISE EXCEPTION 'A5Q_C2_PACKET_IDENTITY'; END IF;
 IF encode(sha256(convert_to(v_packet#>>'{input,input_literal}','UTF8')),'hex') <> v_packet#>>'{input,input_sha256}'
  THEN RAISE EXCEPTION 'A5Q_C2_INPUT_SHA_MISMATCH'; END IF;
 IF (v_packet#>>'{limits,provider_attested}')::boolean IS NOT FALSE OR (v_packet#>>'{limits,real_execution_receipt}')::boolean IS NOT FALSE
  THEN RAISE EXCEPTION 'A5Q_C2_LIMITS_NOT_FALSE'; END IF;
 IF (SELECT status FROM programacion.engineering_work_checkpoints WHERE work_item_id=v_wi AND checkpoint_code=v_cp) IS DISTINCT FROM 'PENDING'
  THEN RAISE EXCEPTION 'A5Q_C2_NOT_PENDING'; END IF;
 SELECT string_agg(checkpoint_code||':'||status,',' ORDER BY sequence_no) INTO v_before_cps
  FROM programacion.engineering_work_checkpoints WHERE work_item_id=v_wi;
 SELECT unit_metadata INTO v_m FROM programacion.engineering_plan_units
  WHERE plan_code=v_plan AND unit_code=v_unit AND work_item_id=v_wi FOR UPDATE;
 IF v_m IS NULL THEN RAISE EXCEPTION 'A5Q_UNIT_NOT_FOUND'; END IF;
 IF v_m#>'{gpt_native_packets_v1,A5Q_C2}' IS NOT NULL AND v_m#>>'{gpt_native_packets_v1,A5Q_C2,packet_sha256}' <> v_packet_sha
  THEN RAISE EXCEPTION 'A5Q_C2_PACKET_DIFFERENT_ALREADY_STORED'; END IF;
 v_before_specs := v_m->'action_specs_v1';
 UPDATE programacion.engineering_plan_units
    SET unit_metadata = v_m || jsonb_build_object('gpt_native_packets_v1',
        COALESCE(v_m->'gpt_native_packets_v1','{}'::jsonb) || jsonb_build_object('A5Q_C2',v_packet))
  WHERE plan_code=v_plan AND unit_code=v_unit AND work_item_id=v_wi;
 SELECT unit_metadata INTO v_m FROM programacion.engineering_plan_units
  WHERE plan_code=v_plan AND unit_code=v_unit AND work_item_id=v_wi;
 v_stored := v_m#>'{gpt_native_packets_v1,A5Q_C2}';
 IF v_stored IS DISTINCT FROM v_packet THEN RAISE EXCEPTION 'A5Q_C2_PACKET_READBACK_MISMATCH'; END IF;
 IF v_m->'action_specs_v1' IS DISTINCT FROM v_before_specs THEN RAISE EXCEPTION 'A5Q_C2_SPECS_CHANGED'; END IF;
 IF NOT EXISTS (SELECT 1 FROM public.lf_eventos WHERE evento_tipo='HANDOFF_DEEP_CONTEXT' AND created_by_execution_id=v_exec) THEN
  INSERT INTO public.lf_eventos(evento_tipo,entidad_tipo,entidad_codigo,descripcion,severidad,origen,created_by_execution_id,payload)
  VALUES('HANDOFF_DEEP_CONTEXT','PROGRAM_PLAN',v_plan||'.A5Q_C2.GPT_NATIVE_HANDOFF',
   'Frozen A5Q_C2 packet handed to GPT Native for a producer run; no acceptance declared.','INFO','DERIVE_FROM_EXECUTION_ID',v_exec,
   jsonb_build_object(
    'evidence_schema_version','operational-event/v2','execution_id',v_exec,
    'producer','ANALYSIS_QUAL_C2_GPT_HANDOFF_V1',
    'purpose','Hand the frozen A5Q_C2 packet to GPT Native so it can produce the stage output in its own chat.',
    'occurred_at',to_char(clock_timestamp() AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"+00:00"'),
    'acceptance_declared',false,
    'subject_ref',v_packet->>'subject_ref','checkpoint',v_cp,'work_item_id',v_wi,
    'packet_location','supabase://programacion.engineering_plan_units/'||v_unit||'#unit_metadata.gpt_native_packets_v1.'||v_cp,
    'packet_sha256',v_packet_sha,'request_sha256',v_packet->>'request_sha256',
    'input_sha256',v_packet#>>'{input,input_sha256}','producer_mode','GPT_NATIVE',
    'evidence_tier',v_packet->>'evidence_tier','provider_attested',false,
    'instructions_for_gpt',v_packet->>'prompt_for_gpt',
    'return_instructions','Reply in the same chat with ONLY the JSON object, unedited. Keep the chat link; the verifier needs the RAW JSON, the chat link and the transcript SHA-256. Do not claim provider attestation.',
    'limits_note','Owner-approved GPT Native in-chat equivalent. Not a provider receipt and not an independent review. The checkpoint stays pending until a captured output is verified.'))
  RETURNING id INTO v_id;
  SELECT payload INTO v_p FROM public.lf_eventos WHERE id=v_id;
  IF v_p->>'packet_sha256' IS DISTINCT FROM v_packet_sha OR v_p->>'instructions_for_gpt' IS DISTINCT FROM v_packet->>'prompt_for_gpt'
   THEN RAISE EXCEPTION 'A5Q_C2_HANDOFF_READBACK_MISMATCH'; END IF;
 END IF;
 SELECT string_agg(checkpoint_code||':'||status,',' ORDER BY sequence_no) INTO v_after_cps
  FROM programacion.engineering_work_checkpoints WHERE work_item_id=v_wi;
 IF v_after_cps IS DISTINCT FROM v_before_cps THEN RAISE EXCEPTION 'A5Q_C2_CHECKPOINTS_CHANGED'; END IF;
END
$a5q_c2_prep$;
COMMIT;
